ini_set('display_errors','0');umask(0077);
header('Cache-Control: no-store, private');header('X-Robots-Tag: noindex, nofollow');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: no-referrer');header('X-Frame-Options: DENY');header("Content-Security-Policy: default-src 'self'; style-src 'self'; img-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'");
session_name('nib_consulta');session_set_cookie_params(['lifetime'=>0,'path'=>'/consulta-inscricao/','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','httponly'=>true,'samesite'=>'Lax']);session_start();$_SESSION['csrf']??=bin2hex(random_bytes(32));
function ch($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function cn(string $v):string{$v=strtr($v,['Á'=>'a','À'=>'a','Â'=>'a','Ã'=>'a','Ä'=>'a','á'=>'a','à'=>'a','â'=>'a','ã'=>'a','ä'=>'a','É'=>'e','Ê'=>'e','È'=>'e','é'=>'e','ê'=>'e','è'=>'e','Í'=>'i','í'=>'i','Ó'=>'o','Ô'=>'o','Õ'=>'o','ó'=>'o','ô'=>'o','õ'=>'o','Ú'=>'u','Ü'=>'u','ú'=>'u','ü'=>'u','Ç'=>'c','ç'=>'c']);return strtolower(trim(preg_replace('/\s+/u',' ',$v)??''));}
function cp(string $v):string{$v=preg_replace('/\D/','',$v)??'';return strlen($v)>11&&str_starts_with($v,'55')?substr($v,2):$v;}
$events=['mulheres-virtuosas'=>['name'=>'Mulheres Virtuosas','folder'=>'mulheres-2026-10-30','paid'=>true,'url'=>'/mulheres-virtuosas.html'],'nxt-camp'=>['name'=>'NXT CAMP','folder'=>'nxt-camp-2026-11-21','paid'=>true,'url'=>'/next/camp-sbgp1-nov26/inscricao.html']];
$base='';$error='';$results=[];$searched=false;$slug=is_string($_GET['evento']??null)?$_GET['evento']:'';
try{
 $web=realpath($_SERVER['DOCUMENT_ROOT']??'');if(!$web||$web==='/')throw new RuntimeException('root');$base=realpath(dirname($web).'/nib-inscricoes-privado')?:'';if(!$base||str_starts_with($base.'/',$web.'/'))throw new RuntimeException('storage');
 $catalog=$base.'/eventos-catalogo.json';if(is_file($catalog)&&!is_link($catalog)){$cat=json_decode((string)file_get_contents($catalog),true,512,JSON_THROW_ON_ERROR);foreach($cat as $key=>$e){if(empty($e['legacy'])&&in_array($e['publication']??'',['publicado','encerrado'],true)&&in_array($e['mode']??'',['pago','gratuito'],true)&&preg_match('/^[a-z0-9-]{1,70}$/D',(string)$key)&&preg_match('/^evento-[a-z0-9-]{1,70}$/D',$e['folder']??''))$events[$key]=['name'=>$e['name'],'folder'=>$e['folder'],'paid'=>$e['mode']==='pago','url'=>'/eventos/?evento='.rawurlencode((string)$key)];}}
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['csrf'],$_POST['csrf'])){http_response_code(403);throw new RuntimeException('csrf');}
  $rate=$base.'/.consulta-rate-'.hash('sha256',$_SERVER['REMOTE_ADDR']??'unknown').'.json';if(is_link($rate))throw new RuntimeException('rate');$lock=fopen($rate,'c+');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('rate');
  try{$r=json_decode((string)stream_get_contents($lock),true);if(!is_array($r)||time()-(int)($r['since']??0)>=900)$r=['count'=>0,'since'=>time()];if((int)$r['count']>=15){http_response_code(429);throw new RuntimeException('limit');}$r['count']++;rewind($lock);ftruncate($lock,0);fwrite($lock,json_encode($r));}finally{flock($lock,LOCK_UN);fclose($lock);}
  $slug=is_string($_POST['evento']??null)?$_POST['evento']:'';$identity=is_string($_POST['identity']??null)?trim($_POST['identity']):'';$phone=is_string($_POST['phone']??null)?cp($_POST['phone']):'';
  if(!isset($events[$slug])||strlen($identity)<3||strlen($identity)>180||!preg_match('/^[1-9][0-9]{9,10}$/D',$phone))throw new RuntimeException('input');
  $ev=$events[$slug];$folder=$base.'/'.$ev['folder'];if(is_link($folder)||!is_dir($folder))throw new RuntimeException('folder');$searched=true;
  foreach(glob($folder.'/*.json')?:[] as $p){if(is_link($p)||!preg_match('/^[a-f0-9]{32}\.json$/D',basename($p)))continue;$row=json_decode((string)file_get_contents($p),true);if(!is_array($row)||!is_string($row['protocol']??null))continue;
   // Busca parcial apenas dentro das inscrições vinculadas ao telefone informado.
   $terms=explode(' ',cn($identity));$name=cn((string)($row['name']??''));$match=strcasecmp($identity,$row['protocol'])===0;
   if(!$match){$match=true;foreach($terms as $term){if($term!==''&&!str_contains($name,$term)){$match=false;break;}}}
   $phones=array_filter([cp((string)($row['whatsapp']??'')),cp((string)($row['phone']??'')),cp((string)($row['guardian_phone']??''))]);
   if($match&&in_array($phone,$phones,true))$results[]=['protocol'=>$row['protocol'],'name'=>(string)($row['name']??''),'reviewed'=>!empty($row['reviewed']),'paid'=>$ev['paid']];
  }
 }
}catch(Throwable $e){$code=$e->getMessage();$error=match($code){'csrf'=>'Sua sessão expirou. Recarregue a página e tente novamente.','limit'=>'Você atingiu o limite de consultas. Aguarde 15 minutos e tente novamente.','input'=>'Selecione o evento e informe pelo menos 3 letras do nome ou o protocolo e o WhatsApp com DDD. ',default=>'A consulta está temporariamente indisponível. Tente novamente mais tarde.'};if(!in_array($code,['input','csrf','limit'],true))error_log('NIB consulta indisponível');}
