type="tel" inputmode="tel" maxlength="30" autocomplete="tel" required><p class="hint">No NXT CAMP, você também pode usar o WhatsApp do responsável informado no cadastro.</p><button type="submit">Consultar inscrição</button></form></section>
<?php if($error):?><p class="message" role="alert"><?=ch($error)?></p><?php elseif($searched):?><section class="results" aria-live="polite"><?php if(!$results):?><div class="panel"><h2>Não localizamos uma inscrição com esses dados</h2><p>Confira o evento, o nome ou o protocolo e o número utilizado no cadastro. Você também pode consultar pelo protocolo.</p><p>Se você já enviou o formulário, procure a organização antes de fazer outra inscrição.</p></div><?php else:?><div class="received"><h2>Inscrições encontradas</h2><p>Seu cadastro está registrado. Não é necessário se inscrever novamente.</p></div><?php foreach($results as $r):?><article class="panel"><span class="status <?=$r['paid']&&!$r['reviewed']?'pending':'ok'?>"><?=!$r['paid']?'Inscrição registrada':($r['reviewed']?'Pagamento conferido':'Pagamento aguardando conferência')?></span><h3><?=ch($r['name'])?></h3><p class="protocol">Protocolo <?=ch($r['protocol'])?></p><p><?=$r['paid']?($r['reviewed']?'A equipe já conferiu o pagamento desta inscrição.':'Seu cadastro foi recebido. A equipe ainda precisa conferir o pagamento. Você não precisa pagar ou cadastrar novamente por esse motivo.'):'Sua inscrição gratuita está registrada.'?></p></article><?php endforeach;?><?php $counts=[];foreach($results as $r){$key=cn($r['name']);$counts[$key]=($counts[$key]??0)+1;}if($counts&&max($counts)>1):?><p class="message">Encontramos mais de um registro com o mesmo nome neste evento. Procure a organização para conferir a possível duplicidade; não faça uma nova inscrição.</p><?php endif;?><?php endif;?></section><?php endif;?>
